UPDATE lf_ops.reglas r SET titulo='Validación de expediente de soporte y contexto restringido',descripcion='B2B-AUTH-006 solo habilita PASSWORD_UPDATE_ONLY tras validación server-side de expediente de soporte con DNI escaneado, aprobación 1 o 2 según política 20, avisos al contacto anterior, auditoría y espera 48 horas. La clave temporal es de un solo uso, no satisface MFA ni crea sesión operativa. Estados pendientes, falsos, vencidos o reutilizados se deniegan con respuesta genérica. El reloj de 48 horas NO empieza con la solicitud. Solo el servidor lo inicia cuando (i) terminaron todas las aprobaciones requeridas según la política aplicable y (ii) cada aviso obligatorio al contacto anterior tiene evidencia de estado ENTREGADO, no solo ACCEPTED/QUEUED/SENT; inicio efectivo = instante del último de esos eventos. Rebote, entrega no confirmada o revocación posterior: estado BLOCKED o PAUSED, sin emisión de clave temporal, reasignación ni sesión; una reanudación exige nueva evidencia de entrega y readback auditado. La clave temporal de un solo uso se genera únicamente DESPUÉS de satisfacer el gate; el contexto PASSWORD_UPDATE_ONLY no sustituye la verificación MFA normal.',valor_config='{"grant_mode":"ONE_TIME_TEMP_PASSWORD_SERVER_VALIDATED","accepted_context":"SUPPORT_RECOVERY_APPROVED_48H","recovery_context_scope":"PASSWORD_UPDATE_ONLY","client_context_promotion":"DENY","recovery_verify_route_id":11,"invalid_recovery_error_id":39,"password_update_screen_id":53,"recovery_verify_screen_id":56,"account_existence_exposure":"DENY","server_verification_required":true,"mfa_satisfied_by_recovery_context":"DENY","new_password_payload_before_verification":"DENY","provider_architecture_security_policy_id":23,"operational_authorization_before_completion":"DENY","recovery_hold_hours":48,"auto_recovery_otp":"DENY","hold_start_event":"AFTER_APPROVALS_AND_CONFIRMED_DELIVERY","delivery_failure_action":"BLOCK_OR_PAUSE","temporary_password_issue_guard":"AFTER_48H_ELAPSED_AND_DELIVERY_STILL_VALID","owner_identity_verified":false}'::jsonb,estado='CANDIDATO' WHERE id=448 AND codigo='B2B-RULE-AUTH-029' AND estado='CANDIDATO' AND encode(pg_catalog.sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex')='f7b59a0fc9768ffed87b7c22a5eb681c73571f83610e994b4891972e68c43c9b';
-- PREIMAGE B2B-RULE-AUTH-037 sha256=b845bb8fe2f4cb700450caea55534b6561287eba9e7ad0c54978a79f6e72ee9a
UPDATE lf_ops.reglas r SET titulo='Validación por soporte de recuperación B2B',descripcion='B2B-AUTH-006 presenta estado genérico de un expediente de soporte, sin envío ni verificación OTP PASSWORD_RECOVERY. El servidor exige DNI escaneado, aprobadores configurables según política 20, aviso previo, auditoría y 48 horas transcurridas antes de emitir clave temporal de uso único. Sin evidencia, bloquear PASSWORD_UPDATE_ONLY y no revelar existencia de cuenta. El reloj de 48 horas NO empieza con la solicitud. Solo el servidor lo inicia cuando (i) terminaron todas las aprobaciones requeridas según la política aplicable y (ii) cada aviso obligatorio al contacto anterior tiene evidencia de estado ENTREGADO, no solo ACCEPTED/QUEUED/SENT; inicio efectivo = instante del último de esos eventos. Rebote, entrega no confirmada o revocación posterior: estado BLOCKED o PAUSED, sin emisión de clave temporal, reasignación ni sesión; una reanudación exige nueva evidencia de entrega y readback auditado. Ante aviso fallido, soporte puede abrir una ruta alternativa gobernada y auditada, sin desbloqueo automático. Contactos candidatos exclusivamente: otro correo o celular previamente registrado y verificado de la misma cuenta antes de iniciar la recuperación, con prueba histórica de titularidad, operación de notificación idempotente y confirmación ENTREGADO; se admite reintento al contacto anterior original. No aceptar nuevos datos declarados durante la solicitud, contactos de un aprobador, terceros ni destinatarios no acreditados. Un contacto secundario NO sustituye por sí solo la notificación obligatoria anterior: la equivalencia y autoridad de sustitución siguen PENDING_HUMAN_DECISION y bloquean el reloj/la liberación hasta aprobación explícita.',valor_config='{"success_scope":"PASSWORD_UPDATE_ONLY","otp_value_logs":"DENY","mfa_satisfaction":"DENY","verify_screen_id":56,"primary_cta_label":"Verificar código","request_screen_id":52,"delivery_execution":"LF_SERVER_ONLY","otp_value_analytics":"DENY","production_authorized":false,"server_side_generation":"REQUIRED","anti_enumeration_rule_id":446,"delivery_provider_status":"PENDING_CREDENTIALS_IMPLEMENTATION","server_side_verification":"REQUIRED","delivery_contract_rule_id":505,"delivery_confirmed_outcome":"DELIVERED","delivery_confirmation_event":"delivered","provider_acceptance_outcome":"ACCEPTED_PENDING_DELIVERY","operational_session_creation":"DENY","delivery_state_contract_rule_id":505,"provider_acceptance_is_delivery":"DENY","webhook_required_before_verify_ui":false,"provider_acceptance_allows_verify_ui":true,"delivery_failure_account_existence_exposure":"DENY","recovery_method":"SUPPORT_DNI_SCANNED","approval_policy_id":20,"hold_hours":48,"auto_otp_challenge":"DENY","temporary_password":"ONE_TIME_AFTER_APPROVAL","hold_start_event":"LAST_REQUIRED_APPROVAL_AND_DELIVERY","notify_old_contact_status":"DELIVERED_REQUIRED","alternate_contact_accepted":"PENDING_HUMAN_DECISION","owner_identity_verified":false}'::jsonb,estado='CANDIDATO' WHERE id=493 AND codigo='B2B-RULE-AUTH-037' AND estado='CANDIDATO' AND encode(pg_catalog.sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex')='b845bb8fe2f4cb700450caea55534b6561287eba9e7ad0c54978a79f6e72ee9a';
-- PREIMAGE B2B-RULE-AUTH-038 sha256=481ebfde98e2fc5ca2a709cb739579d79f85a5a582e98d26153386c98b2df0ca
UPDATE lf_ops.reglas r SET titulo='Espera de recuperación y estados calculados por servidor',descripcion='B2B-AUTH-006 muestra exclusivamente estados normalizados de expediente y espera de 48 horas calculados server-side; no muestra reenvío OTP ni permite que un temporizador del navegador autorice el desbloqueo. Antes de la aprobación, notificación y vencimiento de espera, no habilita PASSWORD_UPDATE_ONLY. En todos los estados mantiene anti-enumeración. El reloj de 48 horas NO empieza con la solicitud. Solo el servidor lo inicia cuando (i) terminaron todas las aprobaciones requeridas según la política aplicable y (ii) cada aviso obligatorio al contacto anterior tiene evidencia de estado ENTREGADO, no solo ACCEPTED/QUEUED/SENT; inicio efectivo = instante del último de esos eventos. Rebote, entrega no confirmada o revocación posterior: estado BLOCKED o PAUSED, sin emisión de clave temporal, reasignación ni sesión; una reanudación exige nueva evidencia de entrega y readback auditado. Tiempo transcurrido y pausa se calculan desde el ledger server-side, sin que el cliente reanude por acción local.',valor_config='{"hardcoded_expiry":"DENY","verify_screen_id":56,"anti_enumeration_required":true,"hardcoded_resend_countdown":"DENY","numeric_thresholds_in_rule":"DENY","recovery_hold_hours":48,"display_source":"SERVER_RECOVERY_CASE","resend_otp_visible":false,"hold_start":"LATEST_OF_REQUIRED_APPROVAL_COMPLETION_AND_DELIVERY","hold_elapsed_calculation":"SERVER_SIDE_ACCUMULATED_ELIGIBLE_INTERVALS","hold_paused_when_delivery_invalid":true,"restart_requires_fresh_delivery_receipt":true,"wait_hours":48,"owner_identity_verified":false}'::jsonb,estado='CANDIDATO' WHERE id=494 AND codigo='B2B-RULE-AUTH-038' AND estado='CANDIDATO' AND encode(pg_catalog.sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex')='481ebfde98e2fc5ca2a709cb739579d79f85a5a582e98d26153386c98b2df0ca';
-- PREIMAGE B2B-RULE-AUTH-042 sha256=20ba67e22439a6526b80d9c4fab232f671b1c951b48b9dd465a9cc81f0159521
UPDATE lf_ops.reglas r SET titulo='Rate limit aislado de recuperación por soporte',descripcion='Las solicitudes de soporte de B2B-AUTH-002/006 consumen un contador independiente de MFA y correos transaccionales; mismo tratamiento para cuenta existente e inexistente y sujeto derivado del correo canónico mediante secreto server-side. La IP solo eleva señal preventiva de abuso; nunca bloquea por sí sola. Ventanas y umbrales provienen de la política central, sin duplicarlos. La recuperación por soporte conserva el mismo tratamiento para cuenta existente/inexistente incluso al pausar el reloj por aviso no entregado; mensajes y códigos observables no revelan si hay expediente real.',valor_config='{"ip_escalation":"RISK_OR_ANTIBOT","ip_hard_limit":"DENY","resource_code":"AUTH_SUPPORT_RECOVERY_REQUEST","ip_signal_mode":"PREVENTIVE_ALERT_ONLY","counter_subject":"PRIVACY_PRESERVING_DERIVED_SUBJECT_KEY","rate_limit_policy_id":7,"abuse_security_policy_id":22,"anti_enumeration_required":true,"counter_subject_derivation":"HMAC(SERVER_CANONICAL_EMAIL_VALUE,SERVER_SECRET)","numeric_thresholds_in_rule":"DENY","anti_bot_security_policy_id":17,"account_existence_dependency":"DENY","functional_operation_isolation":"REQUIRED","counter_subject_secret_location":"RUNTIME_SECRET_OUTSIDE_LF_OPS","counter_consumed_when_account_unknown":true,"other_otp_operation_counter_interference":"DENY","transactional_email_counter_interference":"DENY","functional_operation":"SUPPORT_RECOVERY","automatic_otp_send":"DENY","recovery_failure_ui":"ANTI_ENUMERATION_GENERIC","delivery_state_reveal_to_unauthenticated":"DENY","owner_identity_verified":false}'::jsonb,estado='CANDIDATO' WHERE id=501 AND codigo='B2B-RULE-AUTH-042' AND estado='CANDIDATO' AND encode(pg_catalog.sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex')='20ba67e22439a6526b80d9c4fab232f671b1c951b48b9dd465a9cc81f0159521';
-- PREIMAGE REG_CLIENT_RECOVERY_IDV_OUTCOME_001 sha256=772b74d119e1b471e997432273585bc410f081567bd87c26c58dcfacfb4eb30d
UPDATE lf_ops.reglas r SET titulo='CANDIDATO — Resultados normalizados del step-up de recuperación Cliente',descripcion='La recuperación Cliente por soporte presenta prueba MANUAL_Q11_APPROVED separada de cualquier resultado IDV externo; el proveedor IDV sigue pendiente y selfie está NO ACTIVA. Una prueba manual válida se obtiene solo tras DNI escaneado, creador distinto de los aprobadores configurados y entrega confirmada al otro canal histórico verificado; habilita únicamente LIMITED_ACTIVE, nunca AUTHENTICATED_FULL. Si aviso rebota/no se entrega, falta aprobador o existe objeción del dueño real, el resultado es DENY/REVOKE. No se presenta VERIFIED del proveedor sin integración y QA.',valor_config='{"flow":"RECOVERY_FLOW","front":"CLIENTE","outcomes":{"IDENTITY_VALIDATION_DENIED":{"next":"GENERIC_RECOVERY_FAILURE","rebind":"DENY","operational_access":"DENY"},"IDENTITY_VALIDATION_VERIFIED":{"rebind":"ALLOW_VIA_REG_CLIENT_RECOVERY_REBIND_ATOMIC_001","operational_access":"AFTER_SUCCESSFUL_REBIND_ONLY"},"IDENTITY_VALIDATION_RISK_BLOCKED":{"next":"TEMPORARY_SECURITY_STOP","rebind":"DENY","operational_access":"DENY"},"IDENTITY_VALIDATION_RETRYABLE_FAILURE":{"next":"RETRY_SUBJECT_TO_PROVIDER_POLICY","rebind":"DENY","operational_access":"DENY"},"IDENTITY_VALIDATION_SERVICE_UNAVAILABLE":{"next":"RETRY_LATER_NO_BYPASS","rebind":"DENY","operational_access":"DENY"}},"allowed_outcomes":["IDENTITY_VALIDATION_VERIFIED","IDENTITY_VALIDATION_RETRYABLE_FAILURE","IDENTITY_VALIDATION_DENIED","IDENTITY_VALIDATION_RISK_BLOCKED","IDENTITY_VALIDATION_SERVICE_UNAVAILABLE"],"source_rule_code":"REG_CLIENT_RECOVERY_IDV_STEPUP_001","source_decision_numbers":[71,103,104],"support_can_override_outcome":"DENY","provider_result_normalization":"SERVER_SIDE_REQUIRED","provider_raw_payload_to_client":"DENY","provider_specific_reason_to_client":"DENY","support_proof":"MANUAL_Q11_APPROVED_AND_OTHER_CHANNEL_DELIVERED","verified_outcome_scope":"LIMITED_ACTIVE_ONLY","provider_status":"PENDING_SELECTION","selfie":"INACTIVE_OWNER_DECISION","notification_failed_outcome":"DENY","owner_objection_outcome":"REVOKED","policy_code":"SEC-CLIENT-RECOVERY-LIMITED-ACCESS","identity_verified":false}'::jsonb,estado='CANDIDATO' WHERE id=511 AND codigo='REG_CLIENT_RECOVERY_IDV_OUTCOME_001' AND estado='VIGENTE' AND encode(pg_catalog.sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex')='772b74d119e1b471e997432273585bc410f081567bd87c26c58dcfacfb4eb30d';
-- PREIMAGE REG_CLIENT_RECOVERY_IDV_STEPUP_001 sha256=95185d992bf1c7e03773796030024b3642f26757fcea899f1ed02fda681d42b4
UPDATE lf_ops.reglas r SET titulo='CANDIDATO — Step-up de identidad para recuperación Cliente sin factor anterior',descripcion='REC_001 exige soporte Q11 con DNI escaneado para recuperar sin control del celular anterior: creador diferente de aprobador(es), approvers_required 1 o 2 según política Cliente, y aviso ENTREGADO al OTRO canal histórico ya verificado. Cambia celular: notificar al correo anterior verificado; cambia correo: notificar al celular anterior verificado. Cumplidos estos gates, entrada inmediata exclusivamente LIMITADA; la ventana de seguridad empieza entonces y sus parámetros residen en SEC-CLIENT-RECOVERY-LIMITED-ACCESS.policy_config. Sin entrega, NO acceso limitado: ruta alternativa de soporte gobernada/auditada, sin bypass. Selfie no operativa, IDV sin seleccionar; contacto alterno opcional, no obstaculiza onboarding.',valor_config='{"flow":"RECOVERY_FLOW","front":"CLIENTE","triggers":["OLD_PHONE_UNAVAILABLE","PHONE_MULTI_DNI_RISK_HIGH"],"raw_pii_in_logs":"DENY","provider_binding":"PENDING_CANONICAL_IDV_PROVIDER","rebind_rule_code":"REG_CLIENT_RECOVERY_REBIND_ATOMIC_001","support_override":"DENY","target_route_code":"CLIENT_RECOVERY","raw_pii_in_analytics":"DENY","target_screen_mapping":"REC_001","source_decision_numbers":[71,103,104],"required_identity_outcome":"SUPPORT_MANUAL_APPROVED_WITH_DELIVERED_NOTICE","provider_agnostic_contract":true,"current_phone_control_source":"ONB_002_SAME_SERVER_SESSION","source_architecture_decision":"DEC-CLIENT-AUTH-SESSION-RUNTIME-001","account_rebind_before_verified":"DENY","current_phone_control_required":true,"dni_knowledge_alone_sufficient":false,"raw_provider_payload_to_client":"DENY","knowledge_based_questions_default":"DENY","operational_access_before_verified":"DENY","current_phone_control_alone_sufficient":false,"email_otp_approved_as_client_recovery_factor":false,"manual_recovery_path":"SUPPORT_Q11_IMMEDIATE_LIMITED","support_approvers_source":"CLIENT_RECOVERY_POLICY_CONFIG_APPROVERS_REQUIRED","creator_approver_separation":"REQUIRED","delivery_channel_by_change":"OTHER_PREVIOUS_VERIFIED_CHANNEL","notification_requirement":"DELIVERED","selfie":"INACTIVE","idv_provider":"PENDING_SELECTION","alternate_contact_onboarding":"OPTIONAL","policy_code":"SEC-CLIENT-RECOVERY-LIMITED-ACCESS","identity_verified":false}'::jsonb,estado='CANDIDATO' WHERE id=510 AND codigo='REG_CLIENT_RECOVERY_IDV_STEPUP_001' AND estado='VIGENTE' AND encode(pg_catalog.sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex')='95185d992bf1c7e03773796030024b3642f26757fcea899f1ed02fda681d42b4';
-- PREIMAGE REG_CLIENT_RECOVERY_PHONE_CONTROL_001 sha256=2043f8575951db0e61cdeeec58624f22c035425e929096ae973b9ef159a89dfa
UPDATE lf_ops.reglas r SET titulo='CANDIDATO — Recuperación Cliente reutiliza el celular actual ya verificado',descripcion='El celular candidato verificado en ONB_002 prueba su control, no identidad, y no abre acceso por sí solo. En recuperación sin celular anterior se requiere expediente Q11, aprobadores configurables y aviso ENTREGADO al correo anterior verificado (canal independiente); para cambio de correo el aviso corresponde al celular anterior verificado. No forzar un contacto secundario durante ONB_004: es opcional para onboarding, aunque recuperar sin canal histórico verificado queda fail-closed con soporte alternativo auditado. Tras gates puede abrirse sesión LIMITED_ACTIVE inmediata, no sesión plena. El cambio posterior de correo/celular se rige por policy_config durante la ventana.',valor_config='{"source_state":"RECOVERY_FLOW","source_screen":"ONB_003","target_route_code":"CLIENT_RECOVERY","current_phone_role":"NEW_VERIFIED_PHONE_CANDIDATE","reask_current_phone":"DENY","show_full_old_phone":"DENY","ask_old_phone_access":true,"old_phone_accessible":"VERIFY_OLD_PHONE_OTP","old_phone_otp_channel":"whatsapp","old_phone_unavailable":"SUPPORT_Q11_IMMEDIATE_LIMITED_WITH_EMAIL_NOTICE","target_screen_mapping":"REC_001","source_decision_number":103,"old_phone_otp_operation":"OTP_OP_RECUPERAR_CLAVE","old_phone_otp_field_code":"CAMPO_OTP_CODE","repeat_current_phone_otp":false,"source_architecture_decision":"DEC-CLIENT-AUTH-SESSION-RUNTIME-001","current_verified_phone_source":"ONB_001_PLUS_ONB_002","identity_validation_rule_code":"REG_IDV_PROGRESSIVE_001","same_session_binding_required":true,"phone_recovery_previous_notice":"PREVIOUS_VERIFIED_EMAIL","email_recovery_previous_notice":"PREVIOUS_VERIFIED_PHONE","alternate_contact_required_onboarding":false,"session_after_recovery":"LIMITED_ACTIVE","policy_code":"SEC-CLIENT-RECOVERY-LIMITED-ACCESS","identity_verified":false}'::jsonb,estado='CANDIDATO' WHERE id=507 AND codigo='REG_CLIENT_RECOVERY_PHONE_CONTROL_001' AND estado='VIGENTE' AND encode(pg_catalog.sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex')='2043f8575951db0e61cdeeec58624f22c035425e929096ae973b9ef159a89dfa';
-- PREIMAGE REG_CLIENT_RECOVERY_REBIND_ATOMIC_001 sha256=88b650cd7f9c964281f40b23823c3000b0da9bf91d3b5ef423d453f2129f5557
UPDATE lf_ops.reglas r SET titulo='CANDIDATO — Reasignación de celular de cuenta Cliente atómica e idempotente',descripcion='En REC_001 la reasignación gobernada y atómica para habilitar entrada limitada puede proceder inmediatamente tras DNI escaneado, aprobaciones configurables (creador distinto de los aprobadores), OTP de celular nuevo en sesión ONB_002 vigente y aviso DELIVERED al otro contacto anterior verificado. No aguarda la expiración de ventana para crear una sesión LIMITADA, pero NO autoriza cambios nuevos de datos de contacto desde esa sesión. Antes del commit confirmar unicidad, ausencia de objeción del dueño real y entrega/auditoría; fallo no modifica vínculos ni crea acceso. La ventana y restricciones se resuelven desde política Cliente en lf_ops.politicas_seguridad, no valores escritos en la regla. Revocar sesión y tokens ante objeción verificada.',valor_config='{"idempotency":"REQUIRED","atomic_commit":"REQUIRED","audit_storage":"lf_client.security_events","auth_provider":"SUPABASE_AUTH","audit_rule_code":"REG_AUD_004","raw_dni_in_logs":"DENY","raw_phone_in_logs":"DENY","concurrent_conflict":"GENERIC_FAILURE_NO_PARTIAL_COMMIT","auth_principal_rebind":"UPDATE_CLIENT_ACCOUNT_AUTH_USER_ID_ATOMICALLY_AFTER_VERIFIED_RECOVERY","source_decision_number":103,"account_binding_storage":"lf_client.client_accounts + lf_client.client_phone_bindings","old_phone_otp_operation":"OTP_OP_RECUPERAR_CLAVE","accepted_recovery_proofs":["OLD_PHONE_OTP_VERIFIED","IDENTITY_VALIDATION_VERIFIED","SUPPORT_Q11_APPROVED_DELIVERED_LIMITED"],"current_phone_otp_source":"ONB_002_SAME_SERVER_SESSION","precommit_risk_rule_code":"REG_RISK_PHONE_MULTI_DNI_001","identity_stepup_rule_code":"REG_CLIENT_RECOVERY_IDV_STEPUP_001","current_phone_otp_required":true,"identity_outcome_rule_code":"REG_CLIENT_RECOVERY_IDV_OUTCOME_001","post_rebind_access_rule_code":"REG_CLIENT_RECOVERY_ACCESS_AFTER_REBIND_001","source_architecture_decision":"DEC-CLIENT-AUTH-SESSION-RUNTIME-001","target_phone_uniqueness_rule":"REG_UNI_002","old_principal_business_access":"REVOKE_IMMEDIATELY","old_principal_session_revocation":"SERVER_SIDE_REQUIRED","operational_access_before_commit":"DENY","invalidate_previous_phone_binding":true,"manual_support_commit_gate":"APPROVED_AND_OTHER_PREVIOUS_VERIFIED_CHANNEL_DELIVERED","rebind_success_session":"LIMITED_ACTIVE","restricted_window_parameter_source":"SEC-CLIENT-RECOVERY-LIMITED-ACCESS","require_window_elapsed_for_limited_access":false,"owner_objection_revokes_session":true,"identity_verified":false}'::jsonb,estado='CANDIDATO' WHERE id=508 AND codigo='REG_CLIENT_RECOVERY_REBIND_ATOMIC_001' AND estado='VIGENTE' AND encode(pg_catalog.sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex')='88b650cd7f9c964281f40b23823c3000b0da9bf91d3b5ef423d453f2129f5557';
-- PREIMAGE REG_ONB002_UI_STATES_001 sha256=60d5b3105f550a927efe8bcaede671cbd9e8afef83b610ec68bc18207382f8b0
UPDATE lf_ops.reglas r SET titulo='ONB_002 — estados OTP y SMS por soporte',descripcion='ONB_002 conserva estados A normal, B contador agotado y C OTP incorrecto; tiempos y CTA consumen contratos server-side y tokens de diseño. Ante fallo de WhatsApp no activa SMS automáticamente. SMS Intico solo aparece por contingencia habilitada por soporte con auditoría; en caso contrario permanece oculto. El OTP demuestra control del celular, no identidad civil. Contingencia SMS Intico sólo si soporte la habilitó. Si el usuario deriva a recuperación REC_001, el OTP de ONB_002 no inicia las 48 horas ni habilita readbind por sí solo; rige la prueba de aprobación y entrega de aviso histórico de Q11. Selfie: NO_AUTORIZADA_POR_AHORA, no implementada, sin reglas operativas, sin captura ni envío; proveedor IDV PENDING_SELECTION y sin atribución de VERIFIED automático.',valor_config='{"title":"Te enviamos un código","state_A":{"code":"NORMAL","timer_text":"(00:45)","resend_label":"Reenviar código","resend_muted":true,"cta_visual_state":"ACTIVE_GREEN","timer_underlined":false,"resend_underlined":true},"state_B":{"code":"COUNTER_EXHAUSTED","resend_label":"Reenviar código","cta_visual_state":"PRIMARY_TOKEN","sms_fallback_visibility":"HIDE_UNLESS_SUPPORT_ACTIVATED","runtime_timing_status":"SERVER_POLICY_REQUIRED"},"state_C":{"code":"INVALID_CODE","error_copy":"Código incorrecto. Revisa e intenta de nuevo.","otp_border":"ERROR_RED","cta_visual_state":"ACTIVE_GREEN"},"otp_slots":6,"layout_shift":false,"runtime_refs":["REG_RATE_005","REG_SEG_001","REG_SEG_002","OTP_POL_DEFAULT"],"vertical_anchors":{"h1":"MATCH_ONB001_H1","trust_row":"MATCH_ONB001_TRUST_ROW","primary_cta":"MATCH_ONB001_PRIMARY_CTA"},"error_line_reserved":true,"source_visual_decision":"VD_CLIENT_ONB002_WEB_V06_20260820","sms_fallback_mode":"SUPPORT_ONLY","sms_provider":"INTICO","auto_sms_fallback":"DENY","recovery_timer_started_by_current_phone_otp":false,"selfie_recovery_path":"INACTIVE","idv_provider_status":"PENDING_SELECTION","owner_identity_verified":false}'::jsonb,estado='VIGENTE' WHERE id=568 AND codigo='REG_ONB002_UI_STATES_001' AND estado='VIGENTE' AND encode(pg_catalog.sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex')='60d5b3105f550a927efe8bcaede671cbd9e8afef83b610ec68bc18207382f8b0';
-- PREIMAGE REG_CLIENT_RECOVERY_ACCESS_AFTER_REBIND_001 sha256=77689e352c330caa41e9355d6f5606483d19159485ab76ad60e34434fe60778a
UPDATE lf_ops.reglas r SET titulo='CANDIDATO — Acceso inmediato limitado tras recuperación gobernada',descripcion='REC_001, tras expediente de soporte con DNI escaneado, aprobaciones requeridas y aviso ENTREGADO al otro canal previamente verificado, permite entrada INMEDIATA en sesión LIMITADA emitida y autorizada por servidor. Nunca concede una sesión plena por la mera reasignación. Acciones permitidas, acciones temporalmente bloqueadas y duración de ventana se consultan exclusivamente desde SEC-CLIENT-RECOVERY-LIMITED-ACCESS.policy_config. El cliente puede ver deuda/cuotas y pagar obligaciones existentes (cuotas o pago único); no puede cambiar credenciales/contactos, aceptar ofertas o planes nuevos, recibir/solicitar Carta de No Adeudo ni modificar medio de pago guardado hasta fin de ventana. Una objeción autenticada del dueño real revoca la sesión y tokens. Ausencia de entrega bloquea totalmente el acceso limitado y deriva a soporte.',valor_config='{"flow":"RECOVERY_FLOW","front":"CLIENTE","rebind_model":"ATOMIC_BUSINESS_CLIENT_AUTH_PRINCIPAL_REBIND","auth_provider":"SUPABASE_AUTH","post_auth_route":"CLIENT_HOME_ENTRY_GATED_BY_LIMITED_POLICY","success_outcome":"LIMITED_ACTIVE","phone_binding_store":"lf_client.client_phone_bindings","client_session_policy":"SESSION-CLIENT-DEFAULT","business_client_entity":"lf_client.client_accounts","invalid_session_action":"RESTART_FROM_ONB_001","invalid_session_states":["EXPIRED","BLOCKED","UNVERIFIED","PHONE_BINDING_CHANGED"],"required_rebind_outcome":"REBIND_COMMITTED","source_decision_numbers":[71,103,104],"session_context_contract":"public.fn_lf_client_session_context","required_rebind_rule_code":"REG_CLIENT_RECOVERY_REBIND_ATOMIC_001","session_must_remain_valid":true,"current_phone_proof_source":"ONB_002_SAME_SERVER_SESSION","session_creation_authority":"SERVER_ONLY","source_architecture_decision":"DEC-CLIENT-AUTH-SESSION-RUNTIME-001","old_principal_business_access":"REVOKE_IMMEDIATELY","old_principal_session_revocation":"SERVER_SIDE_REQUIRED","post_auth_home_resolver_rule_code":"REG_CLIENT_AUTH_HOME_RESOLUTION_001","partial_recovery_session_promotion":"DENY","repeat_current_phone_otp_after_successful_rebind":false,"session_permission_mode":"LIMITED_ACTIVE","restricted_window_policy_code":"SEC-CLIENT-RECOVERY-LIMITED-ACCESS","full_session_after_rebind":"DENY","owner_objection_action":"REVOKE_SESSION","failed_notification":"DENY_LIMITED","identity_verified":false}'::jsonb,estado='CANDIDATO' WHERE id=513 AND codigo='REG_CLIENT_RECOVERY_ACCESS_AFTER_REBIND_001' AND estado='VIGENTE' AND encode(pg_catalog.sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex')='77689e352c330caa41e9355d6f5606483d19159485ab76ad60e34434fe60778a';
-- CANDIDATO INSERT B2B-RULE-RECOVERY-SUPPORT-001 association only B2B-AUTH-002,B2B-AUTH-003,B2B-AUTH-006
WITH ins AS (INSERT INTO lf_ops.reglas(codigo,categoria,titulo,descripcion,valor_config,estado,origen,pendiente_decision,created_by) VALUES('B2B-RULE-RECOVERY-SUPPORT-001','AUTH','Recuperación asistida B2B con 48 horas y clave temporal','Soporte registra DNI escaneado; la política central 20 determina 1 o 2 aprobadores (inicial 1). Exigir aviso al contacto previo, auditoría y 48 horas antes de emitir clave temporal de uso único limitada a contraseña nueva. No ofrecer OTP PASSWORD_RECOVERY ni establecer sesión antes de nuevo login y MFA conforme a política. Si falta evidencia, bloquear sin revelar existencia de usuario. El reloj de 48 horas NO empieza con la solicitud. Solo el servidor lo inicia cuando (i) terminaron todas las aprobaciones requeridas según la política aplicable y (ii) cada aviso obligatorio al contacto anterior tiene evidencia de estado ENTREGADO, no solo ACCEPTED/QUEUED/SENT; inicio efectivo = instante del último de esos eventos. Rebote, entrega no confirmada o revocación posterior: estado BLOCKED o PAUSED, sin emisión de clave temporal, reasignación ni sesión; una reanudación exige nueva evidencia de entrega y readback auditado. Ante aviso fallido, soporte puede abrir una ruta alternativa gobernada y auditada, sin desbloqueo automático. Contactos candidatos exclusivamente: otro correo o celular previamente registrado y verificado de la misma cuenta antes de iniciar la recuperación, con prueba histórica de titularidad, operación de notificación idempotente y confirmación ENTREGADO; se admite reintento al contacto anterior original. No aceptar nuevos datos declarados durante la solicitud, contactos de un aprobador, terceros ni destinatarios no acreditados. Un contacto secundario NO sustituye por sí solo la notificación obligatoria anterior: la equivalencia y autoridad de sustitución siguen PENDING_HUMAN_DECISION y bloquean el reloj/la liberación hasta aprobación explícita.','{"approvers_policy_id":20,"initial_approvers_required":1,"hold_hours":48,"document":"SCANNED_DNI","previous_contact_notification":true,"audit":true,"temporary_password":"ONE_TIME","state":"PROPOSED_NOT_ACTIVE","hold_start":"AFTER_ALL_APPROVALS_AND_PREVIOUS_DELIVERED","delivery_failure":"BLOCK_OR_PAUSE","alt_contacts":"CANDIDATE_PENDING_OWNER_AUTHORIZATION","identity_verified":false}'::jsonb,'CANDIDATO','LF_OWNER_DOCUMENTARY_PROPOSAL',true,'ARCHITECT_DRAFT') RETURNING id) INSERT INTO lf_ops.reglas_pantallas(regla_id,pantalla_id,nota) SELECT ins.id,p.pantalla_id,'CANDIDATO_NO_PRODUCTION' FROM ins CROSS JOIN (VALUES (52),(53),(56)) p(pantalla_id);
-- CANDIDATO INSERT REG_CLIENT_RECOVERY_SUPPORT_Q11_001 association only REC_001
WITH ins AS (INSERT INTO lf_ops.reglas(codigo,categoria,titulo,descripcion,valor_config,estado,origen,pendiente_decision,created_by) VALUES('REG_CLIENT_RECOVERY_SUPPORT_Q11_001','RECOVERY','CANDIDATO — Recuperación Cliente Q11: entrada limitada inmediata','REC_001 recibe solicitud de soporte con DNI escaneado; la creación del expediente y su aprobación corresponden a personas distintas. Número de aprobadores conforme a approvers_required en la política Cliente central. El aviso al contacto anterior usa el OTRO canal previamente verificado y requiere DELIVERED. Si entrega y aprobaciones son válidas, conceder LIMITED_ACTIVE inmediatamente, sin esperar la ventana de seguridad. Acción y duración restringidas proceden de policy_config; objeción del dueño real revoca sesión. Selfie no activa, IDV sin seleccionar.','{"policy_code":"SEC-CLIENT-RECOVERY-LIMITED-ACCESS","required_support_dni":true,"creator_different_from_approvers":true,"approvers_required_source":"POLICY_CONFIG","other_previous_contact_required":true,"delivery":"DELIVERED","session_grant":"LIMITED_ACTIVE_IMMEDIATE","wait_to_enter":false,"blocked_actions_source":"POLICY_CONFIG","selfie":"NO","idv":"PENDING_SELECTION","status":"CANDIDATO","identity_verified":false}'::jsonb,'CANDIDATO','LF_OWNER_DOCUMENTARY_PROPOSAL',true,'ARCHITECT_DRAFT') RETURNING id) INSERT INTO lf_ops.reglas_pantallas(regla_id,pantalla_id,nota) SELECT ins.id,p.pantalla_id,'CANDIDATO_NO_PRODUCTION' FROM ins CROSS JOIN (VALUES (58)) p(pantalla_id);
-- CANDIDATO INSERT REG_ONB002_SMS_SUPPORT_GATE_001 association only ONB_002
WITH ins AS (INSERT INTO lf_ops.reglas(codigo,categoria,titulo,descripcion,valor_config,estado,origen,pendiente_decision,created_by) VALUES('REG_ONB002_SMS_SUPPORT_GATE_001','AUTH','SMS Intico como contingencia no automática','En ONB_002 el canal de OTP Cliente es WhatsApp. Ante falla no activar fallback SMS automáticamente: registrar incidente, permitir reintento según política y comunicar a soporte. Solo soporte puede habilitar SMS Intico con evidencia auditable; el frontend no selecciona proveedor, no duplica OTP ni convierte control de teléfono en identidad personal. La activación de soporte SMS no inicia ni levanta la espera de recuperación Q11. Selfie: NO_AUTORIZADA_POR_AHORA, no implementada, sin reglas operativas, sin captura ni envío; proveedor IDV PENDING_SELECTION y sin atribución de VERIFIED automático.','{"channel":"WHATSAPP","contingency":"INTICO_SMS","activation":"SUPPORT_ONLY","auto_fallback":"DENY","state":"PROPOSED_NOT_ACTIVE","recovery_clock_from_otp":"DENY","selfie":"INACTIVE","identity_verified":false}'::jsonb,'CANDIDATO','LF_OWNER_DOCUMENTARY_PROPOSAL',true,'ARCHITECT_DRAFT') RETURNING id) INSERT INTO lf_ops.reglas_pantallas(regla_id,pantalla_id,nota) SELECT ins.id,p.pantalla_id,'CANDIDATO_NO_PRODUCTION' FROM ins CROSS JOIN (VALUES (2)) p(pantalla_id);
-- CANDIDATO INSERT B2B-RULE-RECOVERY-MFA-SEPARATION-001 association only B2B-AUTH-004
WITH ins AS (INSERT INTO lf_ops.reglas(codigo,categoria,titulo,descripcion,valor_config,estado,origen,pendiente_decision,created_by) VALUES('B2B-RULE-RECOVERY-MFA-SEPARATION-001','AUTH','MFA B2B no hereda aprobación ni clave temporal de recuperación','B2B-AUTH-004 solo concluye MFA cuando LF_AUTH_BOUNDARY verifica OTP por correo Brevo conforme a política vigente. Ni la clave temporal de recuperación, ni la aprobación de soporte, ni el aviso entregado, ni las 48 horas satisfacen MFA, crean sesión o eligen factor. La entrega Brevo requiere implementación y QA; no hay bypass SMS automático ni passkeys. Esta regla es CANDIDATO documental y no modifica AUTH-018/019/020/021/026/047 ni políticas 19/20/23/25.','{"mfa":"SERVER_VERIFIED_EMAIL_BREVO_IF_REQUIRED","recovery_proof_satisfies_mfa":false,"temporary_password_satisfies_mfa":false,"sms":"SUPPORT_CONTINGENCY_ONLY","operational":false,"identity_verified":false}'::jsonb,'CANDIDATO','LF_OWNER_DOCUMENTARY_PROPOSAL',true,'ARCHITECT_DRAFT') RETURNING id) INSERT INTO lf_ops.reglas_pantallas(regla_id,pantalla_id,nota) SELECT ins.id,p.pantalla_id,'CANDIDATO_NO_PRODUCTION' FROM ins CROSS JOIN (VALUES (54)) p(pantalla_id);
-- CANDIDATO INSERT B2B-RULE-RECOVERY-ALTERNATE-CONTACT-001 association only B2B-AUTH-002,B2B-AUTH-006
WITH ins AS (INSERT INTO lf_ops.reglas(codigo,categoria,titulo,descripcion,valor_config,estado,origen,pendiente_decision,created_by) VALUES('B2B-RULE-RECOVERY-ALTERNATE-CONTACT-001','RECOVERY','Notificación B2B entregada antes del reloj; contingencia de contacto','El reloj de 48 horas NO empieza con la solicitud. Solo el servidor lo inicia cuando (i) terminaron todas las aprobaciones requeridas según la política aplicable y (ii) cada aviso obligatorio al contacto anterior tiene evidencia de estado ENTREGADO, no solo ACCEPTED/QUEUED/SENT; inicio efectivo = instante del último de esos eventos. Rebote, entrega no confirmada o revocación posterior: estado BLOCKED o PAUSED, sin emisión de clave temporal, reasignación ni sesión; una reanudación exige nueva evidencia de entrega y readback auditado. Ante aviso fallido, soporte puede abrir una ruta alternativa gobernada y auditada, sin desbloqueo automático. Contactos candidatos exclusivamente: otro correo o celular previamente registrado y verificado de la misma cuenta antes de iniciar la recuperación, con prueba histórica de titularidad, operación de notificación idempotente y confirmación ENTREGADO; se admite reintento al contacto anterior original. No aceptar nuevos datos declarados durante la solicitud, contactos de un aprobador, terceros ni destinatarios no acreditados. Un contacto secundario NO sustituye por sí solo la notificación obligatoria anterior: la equivalencia y autoridad de sustitución siguen PENDING_HUMAN_DECISION y bloquean el reloj/la liberación hasta aprobación explícita. Solo contar 48 horas de tiempo elegible; no emitir clave temporal si aviso falló o está en PAUSED. approvers_required se resuelve desde política 20 y no se asume implementado hasta readback real.','{"wait_hours":48,"hold_start":"LAST_APPROVAL_AND_DELIVERED","approval_source":"SECURITY_POLICY_20_APPROVERS_REQUIRED_PENDING_BINDING","delivery_receipt":"DELIVERED_ONLY","failure":"BLOCK_OR_PAUSE","secondary_contact_qualifies":"PENDING_HUMAN_DECISION","status":"PROPOSAL","identity_verified":false}'::jsonb,'CANDIDATO','LF_OWNER_DOCUMENTARY_PROPOSAL',true,'ARCHITECT_DRAFT') RETURNING id) INSERT INTO lf_ops.reglas_pantallas(regla_id,pantalla_id,nota) SELECT ins.id,p.pantalla_id,'CANDIDATO_NO_PRODUCTION' FROM ins CROSS JOIN (VALUES (52),(56)) p(pantalla_id);
-- CANDIDATO INSERT REG_CLIENT_RECOVERY_ALTERNATE_CONTACT_001 association only REC_001
WITH ins AS (INSERT INTO lf_ops.reglas(codigo,categoria,titulo,descripcion,valor_config,estado,origen,pendiente_decision,created_by) VALUES('REG_CLIENT_RECOVERY_ALTERNATE_CONTACT_001','RECOVERY','CANDIDATO — Aviso al otro canal histórico y contingencia auditada','Al cambiar celular, aviso al correo ANTERIOR previamente verificado; al cambiar correo, aviso al celular ANTERIOR previamente verificado. No exigir contacto alterno en onboarding; registrar uno es opcional. Si el canal histórico falta o el aviso rebota/no está DELIVERED, no conceder acceso LIMITED_ACTIVE; soporte abre incidencia gobernada y auditada, sin habilitación automática ni sustitución tácita. Contactos alternos solo tras autoridad verificable y decisión gobernada.','{"policy_code":"SEC-CLIENT-RECOVERY-LIMITED-ACCESS","notify_phone_change":"PREVIOUS_VERIFIED_EMAIL","notify_email_change":"PREVIOUS_VERIFIED_PHONE","optional_other_contact_onboarding":true,"failed_delivery":"BLOCK_LIMITED_AND_SUPPORT_ALTERNATE","secondary_contact_substitution":"PENDING_HUMAN_DECISION","status":"CANDIDATO","identity_verified":false}'::jsonb,'CANDIDATO','LF_OWNER_DOCUMENTARY_PROPOSAL',true,'ARCHITECT_DRAFT') RETURNING id) INSERT INTO lf_ops.reglas_pantallas(regla_id,pantalla_id,nota) SELECT ins.id,p.pantalla_id,'CANDIDATO_NO_PRODUCTION' FROM ins CROSS JOIN (VALUES (58)) p(pantalla_id);
-- CANDIDATO INSERT REG_CLIENT_RECOVERY_LIMITED_SESSION_001 association only REC_001
WITH ins AS (INSERT INTO lf_ops.reglas(codigo,categoria,titulo,descripcion,valor_config,estado,origen,pendiente_decision,created_by) VALUES('REG_CLIENT_RECOVERY_LIMITED_SESSION_001','autenticacion','CANDIDATO — Sesión Cliente limitada inmediata tras gate de soporte','El backend crea sesión LIMITADA inmediatamente después de recibir todas las aprobaciones requeridas y comprobante DELIVERED de aviso al contacto histórico del otro canal previamente verificado. Las capacidades de lectura de deuda/cuotas y pago de obligaciones existentes se autorizan solo por el resolver server-side contra la política central. Prohibido convertir esta sesión en acceso completo o permitir operaciones fuera de policy_config. Sin entrega no se concede ninguna sesión limitada.','{"policy_code":"SEC-CLIENT-RECOVERY-LIMITED-ACCESS","gate":"APPROVALS_AND_DELIVERED_OTHER_PREVIOUS_CONTACT","mode":"LIMITED_ACTIVE","permission_source":"LF_OPS_POLITICAS_SEGURIDAD","state":"CANDIDATO","identity_verified":false}'::jsonb,'CANDIDATO','LF_OWNER_DOCUMENTARY_PROPOSAL',true,'ARCHITECT_DRAFT') RETURNING id) INSERT INTO lf_ops.reglas_pantallas(regla_id,pantalla_id,nota) SELECT ins.id,p.pantalla_id,'CANDIDATO_NO_PRODUCTION' FROM ins CROSS JOIN (VALUES (58)) p(pantalla_id);
-- CANDIDATO INSERT REG_CLIENT_RECOVERY_WINDOW_GUARD_001 association only REC_001
WITH ins AS (INSERT INTO lf_ops.reglas(codigo,categoria,titulo,descripcion,valor_config,estado,origen,pendiente_decision,created_by) VALUES('REG_CLIENT_RECOVERY_WINDOW_GUARD_001','autenticacion','CANDIDATO — Bloqueo de operaciones durante ventana configurable','Durante la ventana de seguridad de recuperación, el backend permite consultar deuda/cuotas y pagar cuotas o deuda existente en pago único, y deniega cambios de correo, celular, contraseña, aceptación de ofertas o planes nuevos, solicitud/entrega de Carta de No Adeudo y cambios/alta/eliminación de medios de pago guardados. Duración de ventana, allowlist y denylist se resuelven exclusivamente de lf_ops.politicas_seguridad.policy_config; ni UI, ni regla, ni token cliente pueden reemplazar la evaluación server-side. Al finalizar la ventana, reevaluar permisos normales, identidad y auditoría.','{"policy_code":"SEC-CLIENT-RECOVERY-LIMITED-ACCESS","window_source":"POLICY_CONFIG","allowed_actions_source":"POLICY_CONFIG","blocked_actions_source":"POLICY_CONFIG","payment_scope":"EXISTING_DEBT_ONLY","state":"CANDIDATO","identity_verified":false}'::jsonb,'CANDIDATO','LF_OWNER_DOCUMENTARY_PROPOSAL',true,'ARCHITECT_DRAFT') RETURNING id) INSERT INTO lf_ops.reglas_pantallas(regla_id,pantalla_id,nota) SELECT ins.id,p.pantalla_id,'CANDIDATO_NO_PRODUCTION' FROM ins CROSS JOIN (VALUES (58)) p(pantalla_id);
-- CANDIDATO INSERT REG_CLIENT_RECOVERY_OWNER_OBJECTION_001 association only REC_001
WITH ins AS (INSERT INTO lf_ops.reglas(codigo,categoria,titulo,descripcion,valor_config,estado,origen,pendiente_decision,created_by) VALUES('REG_CLIENT_RECOVERY_OWNER_OBJECTION_001','autenticacion','CANDIDATO — Objeción de titular verificado revoca sesión limitada','Una objeción verificada y auditada del titular real ante el aviso de recuperación revoca inmediatamente la sesión LIMITADA y sus tokens; backend bloquea todas las operaciones en curso e impide nuevo acceso basado en el mismo expediente. No confundir un contacto no verificado con objeción autenticada; el comprobante del evento es obligatorio. Ningún soporte puede reactivar la sesión revocada sin nuevo caso gobernado.','{"policy_code":"SEC-CLIENT-RECOVERY-LIMITED-ACCESS","trigger":"REAL_OWNER_OBJECTION_VERIFIED","action":"REVOKE_LIMITED_SESSION","server_session_termination":"REQUIRED","state":"CANDIDATO","identity_verified":false}'::jsonb,'CANDIDATO','LF_OWNER_DOCUMENTARY_PROPOSAL',true,'ARCHITECT_DRAFT') RETURNING id) INSERT INTO lf_ops.reglas_pantallas(regla_id,pantalla_id,nota) SELECT ins.id,p.pantalla_id,'CANDIDATO_NO_PRODUCTION' FROM ins CROSS JOIN (VALUES (58)) p(pantalla_id);
-- NUEVA POLITICA Cliente: solo CANDIDATO, duración/acciones en policy_config
INSERT INTO lf_ops.politicas_seguridad(policy_code,category,description,enforcement_level,policy_config,status) VALUES ('SEC-CLIENT-RECOVERY-LIMITED-ACCESS','CLIENT_RECOVERY','Acceso Cliente inmediato pero LIMITADO por recuperación asistida tras aprobaciones y aviso ENTREGADO por el otro canal previamente verificado. Autoridad de sesión, derechos de lectura y pagos y restricciones por ventana de seguridad se resuelven únicamente desde policy_config; ante error de entrega, falta de canal válido u objeción verificada, fail-closed y revocación de la sesión. El contacto secundario es opcional y no bloquea onboarding.','REQUIRED','{"schema_version":"LF_CLIENT_RECOVERY_LIMITED_ACCESS_POLICY_V1","candidate_only":true,"implementation_status":"PENDING_RUNTIME_GOVERNANCE_AND_QA","recovery_screen_code":"REC_001","session_mode":"LIMITED_ACTIVE","approvers_required":1,"approvers_allowed":[1,2],"creator_must_differ_from_approvers":true,"approval_authority":"SUPPORT_GOVERNED_AUDITED","scanned_dni_required":true,"access_start_gate":["REQUIRED_APPROVALS_COMPLETED","OTHER_PREVIOUS_VERIFIED_CHANNEL_NOTICE_DELIVERED"],"notification_channel_for_change":{"PHONE":"PREVIOUS_VERIFIED_EMAIL","EMAIL":"PREVIOUS_VERIFIED_PHONE"},"delivery_proof_required":"DELIVERED","delivery_failure":"NO_LIMITED_ACCESS_GOVERNED_SUPPORT_ALTERNATIVE","alternate_contact_optional_for_onboarding":true,"alternate_contact_runtime_default":"NOT_REQUIRED","security_window_hours":48,"security_window_start":"LATEST_APPROVAL_AND_DELIVERED_TIMESTAMP","limited_allowed_actions":["DEBT_READ","INSTALLMENTS_READ","PAY_EXISTING_INSTALLMENT","PAY_EXISTING_DEBT_SINGLE"],"limited_blocked_actions":["EMAIL_CHANGE","PHONE_CHANGE","PASSWORD_CHANGE","ACCEPT_NEW_OFFER","ACCEPT_NEW_INSTALLMENT_PLAN","NO_DEBT_LETTER_REQUEST","NO_DEBT_LETTER_DELIVERY","SAVED_PAYMENT_METHOD_CHANGE","SAVED_PAYMENT_METHOD_ADD","SAVED_PAYMENT_METHOD_DELETE"],"payment_must_be_existing_debt":true,"offer_or_new_plan_creation_during_limited":"DENY","no_debt_letter_document_creation_if_settled":"MAY_REMAIN_INTERNAL_PENDING_NO_REQUEST_OR_DELIVERY","objection_event":"REAL_OWNER_OBJECTION_VERIFIED","objection_action":"REVOKE_LIMITED_SESSION_AND_INVALIDATE_TOKENS","unknown_action":"DENY","runtime_clock":"SERVER_SIDE_ONLY","identity_verified":false}'::jsonb,'CANDIDATO');
ROLLBACK;
